export const createHotelsApiClient = (options: ApiClientOptions = {}) =>
  createApiClient<paths>({ ...options, caseMapping });
export type HotelsApiClient = ReturnType<typeof createHotelsApiClient>;

const routes = {
  "getHotels": ["GET","/hotels"],
  "getHotel": ["GET","/hotels/{hotel_id}"],
  "getHotelReviews": ["GET","/hotels/{hotel_id}/reviews"],
  "getRates": ["POST","/rates"],
  "createQuote": ["POST","/quotes"],
  "getQuote": ["GET","/quotes/{quote_id}"],
  "getBookings": ["GET","/bookings"],
  "createBooking": ["POST","/bookings"],
  "getBooking": ["GET","/bookings/{booking_id}"],
  "cancelBooking": ["DELETE","/bookings/{booking_id}"],
  "updateBooking": ["PATCH","/bookings/{booking_id}"],
  "createRebookingQuote": ["POST","/bookings/{booking_id}/quotes"],
} as const;

export function createHotelsApiQueryUtils(client: HotelsApiClient, options?: Partial<TanstackQueryUtilsOptions>) {
  return createTanstackQueryUtils<Pick<operations, keyof typeof routes>>(client, routes, { prefix: "hotels", ...options });
}
